public static int upperBound(int[] arr, int target) {
    int low = 0;                          // left edge of the search range
    int high = arr.length;                // exclusive right edge

    while (low < high) {                  // stop when the answer boundary is found
        int mid = low + (high - low) / 2; // overflow-safe midpoint
        if (arr[mid] <= target) {         // equal is still inside the valid prefix
            low = mid + 1;                // move past the valid prefix
        } else {                          // this is a possible upper-bound index
            high = mid;                   // search left for an earlier candidate
        }
    }
    return low;                           // first index with arr[index] > target
}

