int upperBound(vector<int>& arr, int target) {
    int low = 0;                          // left edge of the search range
    int high = arr.size();                // exclusive right edge

    while (low < high) {                  // narrow the first-greater boundary
        int mid = low + (high - low) / 2; // overflow-safe midpoint
        if (arr[mid] <= target) {         // equal values belong to the prefix
            low = mid + 1;                // continue searching to the right
        } else {                          // arr[mid] can be the answer
            high = mid;                   // retain it and search for an earlier one
        }
    }
    return low;                           // first index with arr[index] > target
}
